// Deduplicação por ID. A lista só é atualizada depois que o webhook confirma o envio.
// O static data do workflow persiste entre execuções de produção (workflow ativo).
const payload = $input.first()?.json ?? {};
const alertas = Array.isArray(payload.alertas) ? payload.alertas : [];
const staticData = $getWorkflowStaticData('global');
const idsJaEnviados = new Set((Array.isArray(staticData.alertasCriticosEnviados) ? staticData.alertasCriticosEnviados : []).map(String));

const novos = alertas.filter(alerta => alerta.id !== undefined && alerta.id !== null && !idsJaEnviados.has(String(alerta.id)));

return novos.map(alerta => ({
  json: {
    ...alerta,
    id_alerta: String(alerta.id),
    referencia: payload.referencia ?? null,
    janela_horas: payload.janela_horas ?? 24
  }
}));

const alertas = $input.all().map(item => item.json);
if (alertas.length === 0) return [];

const primeiro = alertas[0];
const linhas = alertas.map(a => `• Linha ${a.linha} (${a.parada || 'sem parada'}): ${a.percentual}% às ${a.criado_em}`);
const texto = `🚨 ${alertas.length} novo(s) alerta(s) crítico(s) de lotação.\n` +
  `Janela: últimas ${primeiro.janela_horas}h (referência: ${primeiro.referencia || 'não informada'}).\n\n` +
  linhas.join('\n') +
  `\n\n⚠️ Dados sintéticos de demonstração.`;

return [{ json: { text: texto, content: texto, alert_ids: alertas.map(a => String(a.id_alerta)) } }];

// Este nó só executa após o HTTP Request retornar sucesso.
const mensagem = $('Montar mensagem').first().json;
const idsNovos = Array.isArray(mensagem.alert_ids) ? mensagem.alert_ids.map(String) : [];
const staticData = $getWorkflowStaticData('global');
const historico = Array.isArray(staticData.alertasCriticosEnviados) ? staticData.alertasCriticosEnviados.map(String) : [];

staticData.alertasCriticosEnviados = [...new Set([...historico, ...idsNovos])].slice(-10000);

return [{ json: { status: 'registrado', alertas_registrados: idsNovos.length } }];
